// Opportunity cards server: runs as an isolated instance with its own storage.
// A verdict is written into the granted sheet's row through the slot the
// manifest names, using the column names the manifest settings map, and is
// kept in app storage as well so a caller who may only read the sheet
// (a share-link guest) still sees what they decided. Nothing here names a
// tenant, a sheet or a column: all of that is manifest data.
export class App {
	constructor(ctx, env) {
		this.ctx = ctx;
		this.env = env;
	}

	settings() {
		return this.env.CONFIG?.settings ?? {};
	}

	/** Verdicts recorded here, by card number. */
	async verdicts() {
		return this.ctx.storage.kv.get("verdicts") ?? {};
	}

	/**
	 * Record one verdict. Returns where it landed: `sheet` when the row was
	 * updated through the slot, `app` when only app storage holds it (the
	 * caller's role or the grants allow no write, or the column is unmapped).
	 */
	async recordVerdict(number, value) {
		if (value !== "yes" && value !== "no") throw new Error("Unknown verdict");
		const key = String(number);
		const verdicts = await this.verdicts();
		verdicts[key] = { value, at: Date.now() };
		this.ctx.storage.kv.put("verdicts", verdicts);
		const written = await this.writeToSheet(key, value);
		return { number: key, value, storedIn: written ? "sheet" : "app" };
	}

	async writeToSheet(number, value) {
		const settings = this.settings();
		const slot = settings.slot ?? "opportunities";
		const columns = settings.columns ?? {};
		const write = this.env.TEDIX?.outputsWrite;
		if (typeof write !== "function") return false;
		let read;
		try {
			read = await this.env.TEDIX.outputsRead(slot, null);
		} catch {
			return false;
		}
		const sheet = read?.revision?.content;
		if (sheet?.kind !== "sheet") return false;
		const find = (wanted) => {
			const needle = String(wanted ?? "").toLowerCase();
			return sheet.columns.findIndex((column) =>
				String(column).toLowerCase().startsWith(needle),
			);
		};
		const verdictColumn = find(columns.useful ?? "Useful?");
		const numberColumn = find(columns.number ?? "#");
		if (verdictColumn < 0) return false;
		const rowIndex = sheet.rows.findIndex((row, index) =>
			String(numberColumn >= 0 ? row[numberColumn] : index + 1) === number,
		);
		if (rowIndex < 0) return false;
		const rows = sheet.rows.map((row, index) =>
			index === rowIndex
				? row.map((cell, column) => (column === verdictColumn ? value : cell))
				: row,
		);
		try {
			await write(slot, {
				content: { ...sheet, rows },
				expectedRevision: read.revision.revision,
			});
			return true;
		} catch {
			return false;
		}
	}
}

